+    }
+
+    #[test]
+    fn save_report_creates_nested_directories() {
+        let temp = tempfile::TempDir::new().unwrap();
+        let nested = temp.path().join("a").join("b").join("c");
+        let report = build_report("test", "echo hi", Some(0), "err", "retry", &HashMap::new());
+        let path = save_report_to(&report, &nested).unwrap();
+        assert!(path.exists());
+        assert!(nested.is_dir());
+    }
+
+    #[test]
+    fn saved_report_round_trips_through_yaml() {
+        let temp = tempfile::TempDir::new().unwrap();
+        let report = build_report(
+            "bundler",
+            "bundle install",
+            Some(1),
+            "gem error",
+            "retry",
+            &HashMap::new(),
+        );
+        let path = save_report_to(&report, temp.path()).unwrap();
+        let content = std::fs::read_to_string(&path).unwrap();
+        let loaded: FailureReport = serde_yaml::from_str(&content).unwrap();
+
+        assert_eq!(loaded.step_name, report.step_name);
+        assert_eq!(loaded.command_scrubbed, report.command_scrubbed);
+        assert_eq!(loaded.exit_code, report.exit_code);
+        assert_eq!(loaded.error_scrubbed, report.error_scrubbed);
+        assert_eq!(loaded.recovery_action, report.recovery_action);
+        assert_eq!(loaded.bivvy_version, report.bivvy_version);
+        assert_eq!(loaded.platform, report.platform);
+    }
+
+    #[test]
+    fn saved_report_filename_contains_step_name_and_extension() {
+        let temp = tempfile::TempDir::new().unwrap();
+        let report = build_report(
+            "homebrew",
+            "brew install",
+            Some(1),
+            "err",
+            "retry",
+            &HashMap::new(),
+        );
+        let path = save_report_to(&report, temp.path()).unwrap();
+
+        let filename = path.file_name().unwrap().to_str().unwrap();
+        assert!(
+            filename.contains("homebrew"),
+            "filename should contain step name: {}",
+            filename
+        );
+        assert!(
+            filename.ends_with(".yml"),
+            "filename should end with .yml: {}",
+            filename
+        );
+    }
+
+    #[test]
+    fn multiple_reports_with_different_steps_coexist() {
+        let temp = tempfile::TempDir::new().unwrap();
+        let steps = ["bundler", "homebrew", "node"];
+        for step in &steps {
+            let report = build_report(step, "cmd", Some(1), "err", "retry", &HashMap::new());
+            save_report_to(&report, temp.path()).unwrap();
+        }
+        let count = std::fs::read_dir(temp.path()).unwrap().count();
+        assert_eq!(
+            count, 3,
+            "All three reports should be saved as separate files"
+        );
+    }
+
+    #[test]
+    fn rapid_saves_with_same_step_preserve_all_reports() {
+        let temp = tempfile::TempDir::new().unwrap();
+        let num_reports = 5;
+
+        for i in 0..num_reports {
+            let report = build_report(
+                "bundler",
+                &format!("bundle install attempt {}", i),
+                Some(1),
+                &format!("error {}", i),
+                "retry",
+                &HashMap::new(),
+            );
+            save_report_to(&report, temp.path()).unwrap();
+        }
+
+        let count = std::fs::read_dir(temp.path()).unwrap().count();
+        assert_eq!(
+            count, num_reports,
+            "All {} reports should be preserved, but only {} files found. \
+             Events were dropped due to filename collision.",
+            num_reports, count
+        );
+    }
+
+    #[test]
+    fn concurrent_saves_preserve_all_reports() {
+        use std::sync::Arc;
+        use std::thread;
+
+        let temp = tempfile::TempDir::new().unwrap();
+        let dir = Arc::new(temp.path().to_path_buf());
+        let num_threads: usize = 10;
+
+        let handles: Vec<_> = (0..num_threads)
+            .map(|i| {
+                let dir = Arc::clone(&dir);
+                thread::spawn(move || {
+                    let report = build_report(
+                        &format!("step-{}", i),
+                        &format!("cmd-{}", i),
+                        Some(i as i32),
+                        &format!("error {}", i),
+                        "retry",
+                        &HashMap::new(),
+                    );
+                    save_report_to(&report, &dir).unwrap();
+                })
+            })
+            .collect();
+
+        for h in handles {
+            h.join().unwrap();
+        }
+
+        let count = std::fs::read_dir(temp.path()).unwrap().count();
+        assert_eq!(
+            count, num_threads,
+            "All {} reports should be preserved under concurrent writes.",
+            num_threads
+        );
+    }
+
+    #[test]
+    fn prompt_telemetry_shows_report_details_in_messages() {
+        let report = build_report(
+            "bundler",
+            "bundle install",
+            Some(1),
+            "gem build error",
+            "retry",
+            &HashMap::new(),
+        );
+        let mut ui = crate::ui::MockUI::new();
+        ui.set_interactive(true);
+        ui.set_prompt_response("telemetry_failure", "send");
+
+        prompt_telemetry(&mut ui, &report, None).unwrap();
+
+        let messages = ui.messages().join("\n");
+        assert!(messages.contains("bundler"), "Should show step name");
+        assert!(messages.contains("bundle install"), "Should show command");
+        assert!(messages.contains("gem build error"), "Should show error");
+        assert!(messages.contains("retry"), "Should show recovery action");
+    }
+
+    #[test]
+    fn prompt_telemetry_with_unknown_preference_shows_prompt() {
+        let report = build_report("test", "echo test", Some(0), "", "retry", &HashMap::new());
+        let mut ui = crate::ui::MockUI::new();
+        ui.set_interactive(true);
+        ui.set_prompt_response("telemetry_failure", "send");
+
+        prompt_telemetry(&mut ui, &report, Some("unknown_value")).unwrap();
+        assert!(
+            !ui.prompts_shown().is_empty(),
+            "Unknown preference should still show prompt"
+        );
+    }
 }

